    "stem": "Why is Six Sigma important in a business application?",
    "options": [
      "Customers are demanding the use of Six Sigma in many industries.",
      "Organizations must stay profitable to remain in business, and Six Sigma is a powerful tool to that end.",
      "Customers demand that all suppliers use Six Sigma to continually improve products.",
      "Managers demand that Green Belts be trained to support organizations in today’s businesses."
    ],
    "answer": 1,
    "why": "The true value of Six Sigma is the bottom-line results gained by an organization. <b>B. Organizations must stay profitable to remain in business, and Six Sigma is a powerful tool to that end.</b> <span class=\"tb-source-ref\">Source: The ASQ Certified Six Sigma Green Belt Study Guide (2024), Part A I. Overview: Six Sigma and the Organization, Question 1 (print p. 4), I.A.1.</span>",
    "set": 2,
