    "sub": "cssgb-org",
    "stem": "The cause-and-effect, or fishbone, diagram was created by:",
    "options": [
      "W. Edwards Deming.",
      "Joseph M. Juran.",
      "Kaoru Ishikawa.",
      "Genichi Taguchi."
    ],
    "answer": 2,
    "why": "Also called the Ishikawa diagram. Note: Deming tried to Americanize this tool by calling it a feather diagram, but the term never stuck. Taguchi is most known for the loss function and design of experiments (DOEs) using orthogonal arrays. <b>C. Kaoru Ishikawa.</b> <span class=\"tb-source-ref\">Source: The ASQ Certified Six Sigma Green Belt Study Guide (2024), Part A I. Overview: Six Sigma and the Organization, Question 5 (print p. 5), I.A.1.</span>",
    "set": 2,
