    "answer": 3,
    "why": "The first step in planning an audit is to identify the desired requirements of the standard to be reviewed. A good reference here is ISO 19011 for conducting audits. <b>D. what the standards or criteria are to be audited against.</b> <span class=\"tb-source-ref\">Source: The ASQ Certified Six Sigma Green Belt Study Guide (2024), Part A II. Define Phase, Question 43 (print p. 30), II.D.</span>",
