    "why": "Teams typically go through the forming, storming, norming, and performing stages of evolution. This has been shown time and time again and has been well documented in many references. Also, remember that as new team members join the group, the process may need to start over. <b>B. Forming, storming, norming, and performing.</b> <span class=\"tb-source-ref\">Source: The ASQ Certified Six Sigma Green Belt Study Guide (2024), Part A II. Define Phase, Question 59 (print p. 33), II.F.1.</span>",
