    "stem": "What is the formula for the probability of Event A or B occurring when the events are mutually exclusive?",
    "options": [
      "P(A or B) = P(A) + P(B)",
      "P(A and B) = P(A) × P(B)",
      "P(A and B) = P(A) + P(B) − P(A ∩ B)",
      "P(A or B) = P(A) × P(B) − P(A ∩ B)"
    ],
    "answer": 0,
    "why": "Using the general addition rule, P(A) + P(B) − P(A &amp; B). If Events A and B are mutually exclusive, P(A and B) = 0. Therefore, the formula reduces to P(A or B) = P(A) + P(B). <b>A. P(A or B) = P(A) + P(B)</b> <span class=\"tb-source-ref\">Source: The ASQ Certified Six Sigma Green Belt Study Guide (2024), Part A III. Measure Phase, Question 10 (print p. 48), III.B.1.</span>",
