    "answer": 1,
    "why": "To calculate gage R&amp;R, we use: GR&amp;R = √(repeatability² + reproducibility²) = √(0.81² + 5.15²) = 5.21. <b>B. 5.21</b> <span class=\"tb-source-ref\">Source: The ASQ Certified Six Sigma Green Belt Study Guide (2024), Part A III. Measure Phase, Question 80 (print p. 64), III.E.</span>",
